"""Automated pre-publish safety gate tests for the AWS re:Invent briefing pipeline.

This test module validates `data/split_results.json` before `pipeline.py` builds
`index.html` or `docs/results.md`. If any invariant fails, the pipeline halts
immediately so unverified claims or incomplete rejections are never published.
"""

from collections.abc import Mapping
import json
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

import pytest

# Default path to the partitioned pipeline output generated by the lead step.
DEFAULT_SPLIT_FILE: Path = (
    Path(__file__).resolve().parent.parent / "data" / "split_results.json"
)

# Canonical domain required for every confirmed AWS claim.
OFFICIAL_AWS_DOMAIN: str = "aws.amazon.com"

# Sentinel value emitted by the researcher when no verbatim passage matches.
NO_MATCH_SENTINEL: str = "no match"


def load_split_results(file_path: Path = DEFAULT_SPLIT_FILE) -> dict[str, list[dict[str, Any]]]:
    """Load and validate the JSON partition file produced by the pipeline.

    Args:
        file_path: Path to the JSON file containing `confirmed` and `rejected` lists.

    Returns:
        Parsed dictionary containing the partitioned evaluation items.
    """
    # Fail immediately with an actionable message if the pipeline output is missing.
    assert file_path.is_file(), (
        f"Split results file not found: {file_path}. Run pipeline.py first."
    )

    # Parse JSON directly so any JSONDecodeError fails the test naturally.
    raw_data = json.loads(file_path.read_text(encoding="utf-8"))

    # Guard against malformed root payloads before running item-level checks.
    assert isinstance(raw_data, dict), (
        f"Expected JSON object at root of {file_path}, got {type(raw_data).__name__}."
    )

    return raw_data


def extract_source_url(item: Mapping[str, Any]) -> str:
    """Extract the candidate source URL, supporting both current and legacy field names."""
    return str(item.get("source_url") or item.get("url") or "").strip()


def is_official_aws_url(url: str, allowed_domain: str = OFFICIAL_AWS_DOMAIN) -> bool:
    """Return True if `url` points to `aws.amazon.com` or one of its subdomains."""
    if not url:
        return False

    # Normalize hostname casing before checking exact domain or subdomain suffix.
    hostname = (urlparse(url).hostname or "").lower()
    if hostname == allowed_domain:
        return True
    return hostname.endswith(f".{allowed_domain}")


def validate_confirmed_item(item: Mapping[str, Any]) -> None:
    """Enforce all publication invariants for a single confirmed briefing item."""
    candidate_id = str(item.get("candidate_id") or "unknown")
    url = extract_source_url(item)
    quote = str(item.get("quote") or "")
    normalized_quote = quote.strip()

    # Check 1: Confirmed claims must originate strictly from an official AWS domain.
    assert is_official_aws_url(url), (
        f"Confirmed item {candidate_id} lacks an {OFFICIAL_AWS_DOMAIN} URL: got '{url}'"
    )

    # Check 2a: Confirmed claims must carry a non-empty evidence quote.
    assert normalized_quote, (
        f"Confirmed item {candidate_id} has an empty or whitespace-only quote."
    )

    # Check 2b: Confirmed claims must not retain the 'no match' fallback sentinel.
    assert normalized_quote.lower() != NO_MATCH_SENTINEL, (
        f"Confirmed item {candidate_id} lacks a valid quote: got '{quote}'"
    )


def validate_rejected_item(item: Mapping[str, Any]) -> None:
    """Enforce all auditability invariants for a single rejected briefing item."""
    candidate_id = str(item.get("candidate_id") or "unknown")
    reason = str(item.get("reason") or "").strip()

    # Every rejected claim must explain which verification check failed and why.
    assert reason, f"Rejected item {candidate_id} has no stated reason."


@pytest.fixture(name="split_results", scope="module")
def _split_results_fixture() -> dict[str, list[dict[str, Any]]]:
    """Provide the parsed `split_results.json` payload once per test module run."""
    return load_split_results()


def test_confirmed_items_have_aws_url_and_quote(
    split_results: Mapping[str, list[dict[str, Any]]],
) -> None:
    """Verify every confirmed item has a valid `aws.amazon.com` URL and verbatim quote."""
    confirmed_items = split_results.get("confirmed", [])
    assert isinstance(confirmed_items, list), "'confirmed' field must be a list."

    for item in confirmed_items:
        validate_confirmed_item(item)


def test_rejected_items_have_reason(
    split_results: Mapping[str, list[dict[str, Any]]],
) -> None:
    """Verify every rejected item records a non-empty rejection reason."""
    rejected_items = split_results.get("rejected", [])
    assert isinstance(rejected_items, list), "'rejected' field must be a list."

    for item in rejected_items:
        validate_rejected_item(item)
